export function validateSignup(body: unknown): SignupResult {
  const parsed = signupForm.safeParse(body)
  if (!parsed.success) {
    const errors: FieldErrors = {}
    for (const issue of parsed.error.issues) {
      const key = issue.path.map(String).join('.')
      ;(errors[key] ??= []).push(issue.message)
    }
    return { ok: false, errors }
  }
  // z.object strips unknown keys; confirmPassword is dropped explicitly so it is never stored.
  const { confirmPassword: _confirmPassword, ...user } = parsed.data
  return { ok: true, user }
